# TAREAS DE ESCRITURA QUE CONOCE EL CORRECTOR DE LA PROFESORA
# Cada examen nuevo (modelos M1-M8 del curso) se añade aquí con su clave y se vuelve a generar
# el corrector:  python3 build_corrector.py
# La clave es la misma que usa el motor para el código de la oral (A2-U01, A2-M1...).

T1_LEAD = "Conteste a su amigo. En el correo tiene que:"
T2_INSTR = "Elija solo una de las dos opciones. En cada opción tiene que tratar todos los puntos."

def ex(clave, nombre, t1, op1, op2):
    t1.setdefault("lead", T1_LEAD); t1.setdefault("min", 60); t1.setdefault("max", 70)
    op2.setdefault("ficha", [])
    return {"id": clave, "nombre": nombre, "t1": t1,
            "t2": {"instr": T2_INSTR, "op1": op1, "op2": op2, "min": 70, "max": 80}}

